referenceSolutions.javascript:
export function solve(rows, key) {
  const groups = new Map();
  for (const row of rows) {
    const k = String(row[key]);
    groups.set(k, (groups.get(k) ?? 0) + 1);
  }
  return Object.fromEntries(groups);
}

